  "A vendor's state is read from their GSTIN. Vendors without a GSTIN, or from a state not listed, use the default rate. A rate set for one vendor (Edit Rate below) overrides the rules.": "ಮಾರಾಟಗಾರರ ರಾಜ್ಯವನ್ನು ಅವರ GSTIN ನಿಂದ ಗುರುತಿಸಲಾಗುತ್ತದೆ. GSTIN ಇಲ್ಲದ ಅಥವಾ ಪಟ್ಟಿಯಲ್ಲಿಲ್ಲದ ರಾಜ್ಯದ ಮಾರಾಟಗಾರರಿಗೆ ಡೀಫಾಲ್ಟ್ ದರ ಅನ್ವಯಿಸುತ್ತದೆ. ಒಬ್ಬ ಮಾರಾಟಗಾರರಿಗೆ ನಿಗದಿಪಡಿಸಿದ ದರ (ಕೆಳಗಿನ ದರ ಸಂಪಾದಿಸಿ) ನಿಯಮಗಳಿಗಿಂತ ಮೇಲುಗೈ ಪಡೆಯುತ್ತದೆ.",
