  "Sign in again before saving an address": "ವಿಳಾಸ ಉಳಿಸುವ ಮೊದಲು ಮತ್ತೆ ಲಾಗಿನ್ ಆಗಿ",
  "Sign in again before updating your profile": "ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ನವೀಕರಿಸುವ ಮೊದಲು ಮತ್ತೆ ಲಾಗಿನ್ ಆಗಿ",
  "Sign in before saving a catalog item": "ಕ್ಯಾಟಲಾಗ್ ವಸ್ತು ಉಳಿಸುವ ಮೊದಲು ಲಾಗಿನ್ ಆಗಿ",
  "Stock is kept per godown. Pick the branch at the top of the admin panel, then change its stock.": "ದಾಸ್ತಾನನ್ನು ಪ್ರತಿ ಗೋದಾಮಿಗೆ ಪ್ರತ್ಯೇಕವಾಗಿ ಇಡಲಾಗುತ್ತದೆ. ನಿರ್ವಾಹಕ ವಿಭಾಗದ ಮೇಲ್ಭಾಗದಲ್ಲಿ ಶಾಖೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ, ನಂತರ ಅದರ ದಾಸ್ತಾನು ಬದಲಿಸಿ.",
  "The server returned an invalid order update.": "ಸರ್ವರ್ ಅಮಾನ್ಯ ಆರ್ಡರ್ ನವೀಕರಣವನ್ನು ಹಿಂತಿರುಗಿಸಿದೆ.",
  "This order cannot be cancelled": "ಈ ಆರ್ಡರ್ ಅನ್ನು ರದ್ದುಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ",
  "This order has passed the cancellation stage for your account.": "ನಿಮ್ಮ ಖಾತೆಯಿಂದ ಈ ಆರ್ಡರ್ ಅನ್ನು ರದ್ದುಮಾಡುವ ಹಂತ ಮುಗಿದಿದೆ.",
  "This order line cannot be edited from the current account": "ಪ್ರಸ್ತುತ ಖಾತೆಯಿಂದ ಈ ಆರ್ಡರ್ ಸಾಲನ್ನು ಸಂಪಾದಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ",
  "This product cannot be deleted": "ಈ ಉತ್ಪನ್ನವನ್ನು ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ",
  "This product is currently out of stock": "ಈ ಉತ್ಪನ್ನ ಪ್ರಸ್ತುತ ದಾಸ್ತಾನಿನಲ್ಲಿ ಇಲ್ಲ",
  "This product is not in your store.": "ಈ ಉತ್ಪನ್ನ ನಿಮ್ಮ ಅಂಗಡಿಯಲ್ಲಿ ಇಲ್ಲ.",
  "This product is out of stock and has been removed from your cart": "ಈ ಉತ್ಪನ್ನ ದಾಸ್ತಾನಿನಲ್ಲಿ ಇಲ್ಲದ ಕಾರಣ ನಿಮ್ಮ ಕಾರ್ಟ್‌ನಿಂದ ತೆಗೆದುಹಾಕಲಾಗಿದೆ",
  "Try again.": "ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "Unauthorized: Only an Administrator can add purchase batches.": "ಅನುಮತಿ ಇಲ್ಲ: ನಿರ್ವಾಹಕರು ಮಾತ್ರ ಖರೀದಿ ಬ್ಯಾಚ್‌ಗಳನ್ನು ಸೇರಿಸಬಹುದು.",
  "Unauthorized: Only an Administrator can delete purchase batches.": "ಅನುಮತಿ ಇಲ್ಲ: ನಿರ್ವಾಹಕರು ಮಾತ್ರ ಖರೀದಿ ಬ್ಯಾಚ್‌ಗಳನ್ನು ಅಳಿಸಬಹುದು.",
  "Unauthorized: Only an Administrator can modify batch purchase costs.": "ಅನುಮತಿ ಇಲ್ಲ: ನಿರ್ವಾಹಕರು ಮಾತ್ರ ಬ್ಯಾಚ್ ಖರೀದಿ ವೆಚ್ಚವನ್ನು ಬದಲಾಯಿಸಬಹುದು.",
  "Unauthorized: Only an Administrator is permitted to modify pricing and cost.": "ಅನುಮತಿ ಇಲ್ಲ: ಬೆಲೆ ಮತ್ತು ವೆಚ್ಚವನ್ನು ಬದಲಾಯಿಸಲು ನಿರ್ವಾಹಕರಿಗೆ ಮಾತ್ರ ಅನುಮತಿ ಇದೆ.",
  "useApp must be used inside AppProvider": "useApp must be used inside AppProvider",
  "Your vendor profile is not linked yet. Ask an administrator to assign your vendor account.": "ನಿಮ್ಮ ಮಾರಾಟಗಾರರ ಪ್ರೊಫೈಲ್ ಇನ್ನೂ ಜೋಡಣೆಯಾಗಿಲ್ಲ. ನಿಮ್ಮ ಮಾರಾಟಗಾರ ಖಾತೆಯನ್ನು ನಿಯೋಜಿಸಲು ನಿರ್ವಾಹಕರನ್ನು ಕೇಳಿ.",
  "This order's payment is already confirmed": "ಈ ಆರ್ಡರ್‌ನ ಪಾವತಿ ಈಗಾಗಲೇ ದೃಢಪಟ್ಟಿದೆ",
  "This UTR was already used for order {0}": "ಈ UTR ಅನ್ನು ಈಗಾಗಲೇ ಆರ್ಡರ್ {0} ಗೆ ಬಳಸಲಾಗಿದೆ",
  Sheet1: "Sheet1",
  HMAC: "HMAC",
  "{0} | Rice, Sugar & Cooking Oil from Shami Business Ventures": "{0} | Shami Business Ventures ನಿಂದ ಅಕ್ಕಿ, ಸಕ್ಕರೆ ಮತ್ತು ಅಡುಗೆ ಎಣ್ಣೆ",
  "About Us | {0} by Shami Business Ventures Pvt. Ltd.": "ನಮ್ಮ ಬಗ್ಗೆ | Shami Business Ventures Pvt. Ltd. ನ {0}",
  "Every vendor onboarded to the platform is validated for GST registration, FSSAI licensing and warehouse capability. Orders are split by vendor, fulfilled with tracked freight, and invoiced with complete tax breakups so procurement teams can reconcile input credit without follow-ups.": "ವೇದಿಕೆಗೆ ಸೇರುವ ಪ್ರತಿಯೊಬ್ಬ ಮಾರಾಟಗಾರರ GST ನೋಂದಣಿ, FSSAI ಪರವಾನಗಿ ಮತ್ತು ಗೋದಾಮು ಸಾಮರ್ಥ್ಯವನ್ನು ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ. ಆರ್ಡರ್‌ಗಳನ್ನು ಮಾರಾಟಗಾರರ ಪ್ರಕಾರ ವಿಭಜಿಸಿ, ಟ್ರ್ಯಾಕ್ ಮಾಡಲಾದ ಸರಕು ಸಾಗಣೆಯೊಂದಿಗೆ ಪೂರೈಸಲಾಗುತ್ತದೆ ಮತ್ತು ಸಂಪೂರ್ಣ ತೆರಿಗೆ ವಿವರಗಳೊಂದಿಗೆ ಇನ್‌ವಾಯ್ಸ್ ನೀಡಲಾಗುತ್ತದೆ, ಇದರಿಂದ ಖರೀದಿ ತಂಡಗಳು ಹೆಚ್ಚುವರಿ ವಿಚಾರಣೆ ಇಲ್ಲದೆ ಇನ್‌ಪುಟ್ ಕ್ರೆಡಿಟ್ ಹೊಂದಾಣಿಕೆ ಮಾಡಬಹುದು.",
  "Grain Bazar is the online store of Shami Business Ventures Pvt. Ltd.: rice, sugar and cooking oil from verified mills, sold from our godowns in Challakere and Hubli, Karnataka.": "Grain Bazar ಎಂಬುದು Shami Business Ventures Pvt. Ltd. ನ ಆನ್‌ಲೈನ್ ಅಂಗಡಿ: ಪರಿಶೀಲಿತ ಮಿಲ್‌ಗಳ ಅಕ್ಕಿ, ಸಕ್ಕರೆ ಮತ್ತು ಅಡುಗೆ ಎಣ್ಣೆಯನ್ನು ಕರ್ನಾಟಕದ ಚಳ್ಳಕೆರೆ ಮತ್ತು ಹುಬ್ಬಳ್ಳಿಯ ನಮ್ಮ ಗೋದಾಮುಗಳಿಂದ ಮಾರಾಟ ಮಾಡಲಾಗುತ್ತದೆ.",
  "Shami Business Ventures Pvt. Ltd. is a commodity trading and distribution company operating a premium multi-vendor marketplace for sugar, rice, edible oils and pulses. We connect certified mills and regional distributors with retailers, canteens, hotels and institutional buyers across India.": "Shami Business Ventures Pvt. Ltd. ಸಕ್ಕರೆ, ಅಕ್ಕಿ, ಖಾದ್ಯ ತೈಲ ಮತ್ತು ಬೇಳೆಕಾಳುಗಳಿಗಾಗಿ ಪ್ರೀಮಿಯಂ ಬಹು-ಮಾರಾಟಗಾರರ ಮಾರುಕಟ್ಟೆಯನ್ನು ನಡೆಸುವ ಸರಕು ವ್ಯಾಪಾರ ಮತ್ತು ವಿತರಣಾ ಕಂಪನಿಯಾಗಿದೆ. ನಾವು ಪ್ರಮಾಣೀಕೃತ ಮಿಲ್‌ಗಳು ಮತ್ತು ಪ್ರಾದೇಶಿಕ ವಿತರಕರನ್ನು ಭಾರತದಾದ್ಯಂತದ ಚಿಲ್ಲರೆ ವ್ಯಾಪಾರಿಗಳು, ಕ್ಯಾಂಟೀನ್‌ಗಳು, ಹೋಟೆಲ್‌ಗಳು ಮತ್ತು ಸಾಂಸ್ಥಿಕ ಖರೀದಿದಾರರೊಂದಿಗೆ ಸಂಪರ್ಕಿಸುತ್ತೇವೆ.",
