  "The order you are looking for does not exist.": "ನೀವು ಹುಡುಕುತ್ತಿರುವ ಆರ್ಡರ್ ಅಸ್ತಿತ್ವದಲ್ಲಿಲ್ಲ.",
  "The overall timeline advances when every shipment reaches the next stage.": "ಪ್ರತಿ ಸಾಗಣೆಯೂ ಮುಂದಿನ ಹಂತ ತಲುಪಿದಾಗ ಒಟ್ಟಾರೆ ಸಮಯರೇಖೆ ಮುಂದುವರಿಯುತ್ತದೆ.",
  "This order line cannot be returned online": "ಈ ಆರ್ಡರ್ ಸಾಲನ್ನು ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಹಿಂತಿರುಗಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ",
