  "Platform-wide business configuration": "ಇಡೀ ವೇದಿಕೆಯ ವ್ಯಾಪಾರ ಸಂರಚನೆ",
  "Product Card Display": "ಉತ್ಪನ್ನ ಕಾರ್ಡ್ ಪ್ರದರ್ಶನ",
  "Product cards always show the product, pack size, stock and selling price. Switch on the extra details you want customers to see.": "ಉತ್ಪನ್ನ ಕಾರ್ಡ್‌ಗಳು ಯಾವಾಗಲೂ ಉತ್ಪನ್ನ, ಪ್ಯಾಕ್ ಗಾತ್ರ, ದಾಸ್ತಾನು ಮತ್ತು ಮಾರಾಟ ಬೆಲೆಯನ್ನು ತೋರಿಸುತ್ತವೆ. ಗ್ರಾಹಕರು ನೋಡಬೇಕೆಂದಿರುವ ಹೆಚ್ಚುವರಿ ವಿವರಗಳನ್ನು ಆನ್ ಮಾಡಿ.",
  "Rates are copied into new listings and used at checkout. Existing products keep their saved GST rate.": "ದರಗಳನ್ನು ಹೊಸ ಪಟ್ಟಿಗಳಿಗೆ ನಕಲಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ಬಳಸಲಾಗುತ್ತದೆ. ಈಗಿರುವ ಉತ್ಪನ್ನಗಳು ತಮ್ಮ ಉಳಿಸಿದ GST ದರವನ್ನೇ ಉಳಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "Registered address": "ನೋಂದಾಯಿತ ವಿಳಾಸ",
  "Require vendor KYC approval before catalog changes": "ಕ್ಯಾಟಲಾಗ್ ಬದಲಾವಣೆಗೂ ಮುನ್ನ ಮಾರಾಟಗಾರರ KYC ಅನುಮೋದನೆ ಕಡ್ಡಾಯಗೊಳಿಸಿ",
  "Save Display": "ಪ್ರದರ್ಶನ ಉಳಿಸಿ",
  "Save Profile": "ಪ್ರೊಫೈಲ್ ಉಳಿಸಿ",
