  "Save Tax Settings": "ತೆರಿಗೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಿ",
  Security: "ಭದ್ರತೆ",
  "Security & Access": "ಭದ್ರತೆ ಮತ್ತು ಪ್ರವೇಶ",
  "Shami Business Ventures Private Limited": "Shami Business Ventures Private Limited",
  "Show MRP, discount and savings": "MRP, ರಿಯಾಯಿತಿ ಮತ್ತು ಉಳಿತಾಯ ತೋರಿಸಿ",
  "Show ratings and reviews": "ರೇಟಿಂಗ್ ಮತ್ತು ವಿಮರ್ಶೆಗಳನ್ನು ತೋರಿಸಿ",
  "Star ratings and review counts on product cards and the product page, plus the shop's rating filter.": "ಉತ್ಪನ್ನ ಕಾರ್ಡ್‌ಗಳು ಮತ್ತು ಉತ್ಪನ್ನ ಪುಟದಲ್ಲಿ ಸ್ಟಾರ್ ರೇಟಿಂಗ್ ಮತ್ತು ವಿಮರ್ಶೆಗಳ ಸಂಖ್ಯೆ, ಜೊತೆಗೆ ಅಂಗಡಿಯ ರೇಟಿಂಗ್ ಫಿಲ್ಟರ್.",
  Storefront: "ಆನ್‌ಲೈನ್ ಅಂಗಡಿ",
  "Storefront display saved": "ಅಂಗಡಿ ಪ್ರದರ್ಶನ ಉಳಿಸಲಾಗಿದೆ",
  "System Settings": "ಸಿಸ್ಟಮ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
  "System Settings | Shami Business Ventures Admin": "ಸಿಸ್ಟಮ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು | Shami Business Ventures ನಿರ್ವಾಹಕ",
  "Tax & Invoicing": "ತೆರಿಗೆ ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್",
  "The average above is calculated from saved vendor rates. Set an individual vendor’s commission on the": "ಮೇಲಿನ ಸರಾಸರಿಯನ್ನು ಉಳಿಸಿದ ಮಾರಾಟಗಾರರ ದರಗಳಿಂದ ಲೆಕ್ಕಹಾಕಲಾಗಿದೆ. ಪ್ರತ್ಯೇಕ ಮಾರಾಟಗಾರರ ಕಮಿಷನ್ ಅನ್ನು ಇಲ್ಲಿ ನಿಗದಿಪಡಿಸಿ:",
  "The inactivity timeout is enforced in admin browser sessions. Password reset and change forms require at least 8 characters. Admin MFA and additional password-strength rules are not enforced by this app.": "ನಿರ್ವಾಹಕರ ಬ್ರೌಸರ್ ಸೆಷನ್‌ಗಳಲ್ಲಿ ನಿಷ್ಕ್ರಿಯತೆ ಸಮಯಮಿತಿ ಜಾರಿಯಲ್ಲಿದೆ. ಪಾಸ್‌ವರ್ಡ್ ಮರುಹೊಂದಿಸುವ ಮತ್ತು ಬದಲಾಯಿಸುವ ಫಾರ್ಮ್‌ಗಳಿಗೆ ಕನಿಷ್ಠ 8 ಅಕ್ಷರಗಳು ಬೇಕು. ನಿರ್ವಾಹಕ MFA ಮತ್ತು ಹೆಚ್ಚುವರಿ ಪಾಸ್‌ವರ್ಡ್ ಬಲದ ನಿಯಮಗಳನ್ನು ಈ ಆ್ಯಪ್ ಜಾರಿಗೊಳಿಸುವುದಿಲ್ಲ.",
  "Two-factor authentication for admins": "ನಿರ್ವಾಹಕರಿಗೆ ಎರಡು ಹಂತದ ದೃಢೀಕರಣ",
  "Vendor commission rates": "ಮಾರಾಟಗಾರರ ಕಮಿಷನ್ ದರಗಳು",
  "When enabled, PAN, bank proof and business registration documents must be approved before a vendor can submit or edit listings. Vendors with GSTIN also need an approved GST certificate.": "ಇದನ್ನು ಆನ್ ಮಾಡಿದರೆ, ಮಾರಾಟಗಾರರು ಪಟ್ಟಿಗಳನ್ನು ಸಲ್ಲಿಸುವ ಅಥವಾ ಸಂಪಾದಿಸುವ ಮೊದಲು PAN, ಬ್ಯಾಂಕ್ ಪುರಾವೆ ಮತ್ತು ವ್ಯಾಪಾರ ನೋಂದಣಿ ದಾಖಲೆಗಳು ಅನುಮೋದನೆಯಾಗಿರಬೇಕು. GSTIN ಇರುವ ಮಾರಾಟಗಾರರಿಗೆ ಅನುಮೋದಿತ GST ಪ್ರಮಾಣಪತ್ರವೂ ಬೇಕು.",
  ", then confirm. Confirming marks the order paid, like a manual payment.": ", ನಂತರ ದೃಢೀಕರಿಸಿ. ದೃಢೀಕರಿಸಿದರೆ ಕೈಯಾರೆ ಮಾಡಿದ ಪಾವತಿಯಂತೆ ಆರ್ಡರ್ ಪಾವತಿಸಲಾಗಿದೆ ಎಂದು ಗುರುತಿಸಲಾಗುತ್ತದೆ.",
  "{0} marked paid": "{0} ಪಾವತಿಸಲಾಗಿದೆ ಎಂದು ಗುರುತಿಸಲಾಗಿದೆ",
  "{0} to match in the bank": "ಬ್ಯಾಂಕ್‌ನಲ್ಲಿ ಹೊಂದಿಸಬೇಕಾದವು {0}",
  "{0}: UTR rejected": "{0}: UTR ತಿರಸ್ಕರಿಸಲಾಗಿದೆ",
  Action: "ಕ್ರಮ",
  "Business UPI ID": "ವ್ಯಾಪಾರ UPI ID",
  Checked: "ಪರಿಶೀಲಿಸಲಾಗಿದೆ",
  "Checked payments": "ಪರಿಶೀಲಿಸಿದ ಪಾವತಿಗಳು",
  "Confirm {0} for {1}? Only confirm after you see a credit with UTR {2} for this amount in the bank account.": "{1} ಗಾಗಿ {0} ದೃಢೀಕರಿಸಬೇಕೇ? ಬ್ಯಾಂಕ್ ಖಾತೆಯಲ್ಲಿ ಈ ಮೊತ್ತಕ್ಕೆ UTR {2} ಇರುವ ಜಮೆಯನ್ನು ನೋಡಿದ ನಂತರವೇ ದೃಢೀಕರಿಸಿ.",
  "Confirm paid": "ಪಾವತಿ ದೃಢೀಕರಿಸಿ",
  "Confirmed paid": "ಪಾವತಿ ದೃಢೀಕರಿಸಲಾಗಿದೆ",
  "Could not confirm": "ದೃಢೀಕರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
  "Could not reject": "ತಿರಸ್ಕರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
  "Could not save": "ಉಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
  "Customer asked to correct": "ಸರಿಪಡಿಸಲು ಗ್ರಾಹಕರಿಗೆ ತಿಳಿಸಲಾಗಿದೆ",
  "Customers pay the business UPI ID below, and their bank sends the money straight to the bank account that UPI ID is linked to (the company's current account). The website never holds money. Before switching on, scan the ₹1 test QR: your UPI app shows the bank-registered name of the account, and it must be the company's. Every change of the UPI ID is logged below and every admin is notified.": "ಗ್ರಾಹಕರು ಕೆಳಗಿನ ವ್ಯಾಪಾರ UPI ID ಗೆ ಪಾವತಿಸುತ್ತಾರೆ, ಮತ್ತು ಅವರ ಬ್ಯಾಂಕ್ ಆ UPI ID ಜೋಡಣೆಯಾಗಿರುವ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ (ಕಂಪನಿಯ ಚಾಲ್ತಿ ಖಾತೆ) ನೇರವಾಗಿ ಹಣ ಕಳುಹಿಸುತ್ತದೆ. ವೆಬ್‌ಸೈಟ್ ಎಂದಿಗೂ ಹಣವನ್ನು ಇಟ್ಟುಕೊಳ್ಳುವುದಿಲ್ಲ. ಆನ್ ಮಾಡುವ ಮೊದಲು ₹1 ಪರೀಕ್ಷಾ QR ಸ್ಕ್ಯಾನ್ ಮಾಡಿ: ನಿಮ್ಮ UPI ಆ್ಯಪ್ ಖಾತೆಯ ಬ್ಯಾಂಕ್-ನೋಂದಾಯಿತ ಹೆಸರನ್ನು ತೋರಿಸುತ್ತದೆ, ಅದು ಕಂಪನಿಯದೇ ಆಗಿರಬೇಕು. UPI ID ಯ ಪ್ರತಿಯೊಂದು ಬದಲಾವಣೆಯನ್ನು ಕೆಳಗೆ ದಾಖಲಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಎಲ್ಲಾ ನಿರ್ವಾಹಕರಿಗೆ ಸೂಚನೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
  "Demo / mock: settings and payments here are kept only in this browser. No real money moves.": "ಡೆಮೊ / ಮಾದರಿ: ಇಲ್ಲಿನ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಮತ್ತು ಪಾವತಿಗಳು ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಇರುತ್ತವೆ. ನಿಜವಾದ ಹಣ ವರ್ಗಾವಣೆಯಾಗುವುದಿಲ್ಲ.",
  "Direct UPI is on at checkout": "ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ನೇರ UPI ಆನ್ ಆಗಿದೆ",
