  "From the company's current account or business UPI app (PhonePe / Paytm for Business). UPI to a business account has no MDR.": "ಕಂಪನಿಯ ಚಾಲ್ತಿ ಖಾತೆ ಅಥವಾ ವ್ಯಾಪಾರ UPI ಆ್ಯಪ್‌ನಿಂದ (PhonePe / Paytm for Business). ವ್ಯಾಪಾರ ಖಾತೆಗೆ UPI ಪಾವತಿಗೆ MDR ಶುಲ್ಕ ಇಲ್ಲ.",
  "Marked paid": "ಪಾವತಿಸಲಾಗಿದೆ ಎಂದು ಗುರುತಿಸಲಾಗಿದೆ",
