  "Name customers see": "ಗ್ರಾಹಕರಿಗೆ ಕಾಣುವ ಹೆಸರು",
  "No matching credit in the bank account": "ಬ್ಯಾಂಕ್ ಖಾತೆಯಲ್ಲಿ ಹೊಂದುವ ಜಮೆ ಇಲ್ಲ",
