  "Scan with your own UPI app to check the name and UPI ID shown (₹1 test). Do not pay if anything looks wrong.": "ತೋರಿಸಲಾದ ಹೆಸರು ಮತ್ತು UPI ID ಪರಿಶೀಲಿಸಲು ನಿಮ್ಮ UPI ಆ್ಯಪ್‌ನಿಂದ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ (₹1 ಪರೀಕ್ಷೆ). ಏನಾದರೂ ತಪ್ಪಾಗಿ ಕಂಡರೆ ಪಾವತಿಸಬೇಡಿ.",
