  "test email for your newest website order to the": "ನಿಮ್ಮ ಇತ್ತೀಚಿನ ವೆಬ್‌ಸೈಟ್ ಆರ್ಡರ್‌ನ ಪರೀಕ್ಷಾ ಇಮೇಲ್ ಅನ್ನು ಈ",
  "to review": "ಪರಿಶೀಲಿಸಲು",
  "Turn off": "ಆಫ್ ಮಾಡಿ",
  "Turn on": "ಆನ್ ಮಾಡಿ",
  "When a website order reaches Zoho, Zoho Books can email that sales order (official \"Email a sales order\") from your Zoho organization to the addresses below. Zoho workflow email alerts do not fire for orders created by the website, so this is the Zoho route for new-order emails. Needs Zoho re-authorized once with Zoho Books permission.": "ವೆಬ್‌ಸೈಟ್ ಆರ್ಡರ್ Zoho ತಲುಪಿದಾಗ, Zoho Books ಆ ಸೇಲ್ಸ್ ಆರ್ಡರ್ ಅನ್ನು ನಿಮ್ಮ Zoho ಸಂಸ್ಥೆಯಿಂದ ಕೆಳಗಿನ ವಿಳಾಸಗಳಿಗೆ ಇಮೇಲ್ ಮಾಡಬಹುದು (ಅಧಿಕೃತ \"Email a sales order\"). ವೆಬ್‌ಸೈಟ್ ರಚಿಸಿದ ಆರ್ಡರ್‌ಗಳಿಗೆ Zoho ವರ್ಕ್‌ಫ್ಲೋ ಇಮೇಲ್ ಎಚ್ಚರಿಕೆಗಳು ಕಳುಹಿಸಲ್ಪಡುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಹೊಸ ಆರ್ಡರ್ ಇಮೇಲ್‌ಗಳಿಗೆ ಇದು Zoho ಮಾರ್ಗ. Zoho Books ಅನುಮತಿಯೊಂದಿಗೆ Zoho ಅನ್ನು ಒಮ್ಮೆ ಮರು-ಅಧಿಕೃತಗೊಳಿಸಬೇಕು.",
  "Yes, send test email": "ಹೌದು, ಪರೀಕ್ಷಾ ಇಮೇಲ್ ಕಳುಹಿಸಿ",
  "Zoho diagnostics": "Zoho ತಪಾಸಣೆ",
  "Zoho diagnostics | Grain Bazar Admin": "Zoho ತಪಾಸಣೆ | Grain Bazar ನಿರ್ವಾಹಕ",
  "Zoho has more than 2,000 contacts, so contact existence was not checked.": "Zoho ದಲ್ಲಿ 2,000 ಕ್ಕೂ ಹೆಚ್ಚು ಸಂಪರ್ಕಗಳಿವೆ, ಆದ್ದರಿಂದ ಸಂಪರ್ಕಗಳ ಅಸ್ತಿತ್ವವನ್ನು ಪರಿಶೀಲಿಸಿಲ್ಲ.",
  "Zoho items read.": "Zoho ಐಟಂಗಳನ್ನು ಓದಲಾಗಿದೆ.",
  "Zoho order emails": "Zoho ಆರ್ಡರ್ ಇಮೇಲ್‌ಗಳು",
  "Zoho will send a": "Zoho ಕಳುಹಿಸಲಿದೆ:",
  ": it loads the latest copy from Zoho, saves straight to Zoho Commerce, and never overwrites a newer change made in Zoho. Use": ": ಇದು Zoho ಇಂದ ಇತ್ತೀಚಿನ ಪ್ರತಿಯನ್ನು ಲೋಡ್ ಮಾಡುತ್ತದೆ, ನೇರವಾಗಿ Zoho Commerce ಗೆ ಉಳಿಸುತ್ತದೆ, ಮತ್ತು Zoho ದಲ್ಲಿ ಮಾಡಿದ ಹೊಸ ಬದಲಾವಣೆಯನ್ನು ಎಂದಿಗೂ ಮೇಲ್ಬರಹ ಮಾಡುವುದಿಲ್ಲ. ಬಳಸಿ:",
  "· 200 orders per page": "· ಪ್ರತಿ ಪುಟಕ್ಕೆ 200 ಆರ್ಡರ್‌ಗಳು",
  "· Last updated": "· ಕೊನೆಯದಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ",
  "). The integration now validates Indian GSTINs and falls back to consumer status for retail orders. Click Retry to push now.": "). ಸಂಯೋಜನೆಯು ಈಗ ಭಾರತೀಯ GSTIN ಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ ಮತ್ತು ಚಿಲ್ಲರೆ ಆರ್ಡರ್‌ಗಳಿಗೆ ಗ್ರಾಹಕ ಸ್ಥಿತಿಯನ್ನು ಬಳಸುತ್ತದೆ. ಈಗ ಕಳುಹಿಸಲು ಮರುಪ್ರಯತ್ನಿಸಿ ಕ್ಲಿಕ್ ಮಾಡಿ.",
  "{0} completed, {1} failed, {2} needs review.": "{0} ಪೂರ್ಣಗೊಂಡಿವೆ, {1} ವಿಫಲವಾಗಿವೆ, {2} ಪರಿಶೀಲನೆ ಬೇಕು.",
  "{0} contacts, {1} catalogue items, and {2} orders.": "{0} ಸಂಪರ್ಕಗಳು, {1} ಕ್ಯಾಟಲಾಗ್ ಐಟಂಗಳು ಮತ್ತು {2} ಆರ್ಡರ್‌ಗಳು.",
  "{0} from Zoho": "Zoho ಇಂದ {0}",
  "+ New View": "+ ಹೊಸ ವೀಕ್ಷಣೆ",
  "About this connection": "ಈ ಸಂಪರ್ಕದ ಬಗ್ಗೆ",
  "Added automatically when accounts are registered or address/business details change.": "ಖಾತೆಗಳು ನೋಂದಣಿಯಾದಾಗ ಅಥವಾ ವಿಳಾಸ/ವ್ಯಾಪಾರ ವಿವರಗಳು ಬದಲಾದಾಗ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸೇರಿಸಲಾಗುತ್ತದೆ.",
  "Added automatically when customers place orders or when order quantities/status are updated.": "ಗ್ರಾಹಕರು ಆರ್ಡರ್ ಮಾಡಿದಾಗ ಅಥವಾ ಆರ್ಡರ್ ಪ್ರಮಾಣ/ಸ್ಥಿತಿ ನವೀಕರಿಸಿದಾಗ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸೇರಿಸಲಾಗುತ್ತದೆ.",
  "Added automatically when products are approved or updated in Grain Bazar.": "Grain Bazar ನಲ್ಲಿ ಉತ್ಪನ್ನಗಳು ಅನುಮೋದನೆಯಾದಾಗ ಅಥವಾ ನವೀಕರಿಸಿದಾಗ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸೇರಿಸಲಾಗುತ್ತದೆ.",
  "Admin-only Zoho snapshots, refreshed when you sync": "ನಿರ್ವಾಹಕರಿಗೆ ಮಾತ್ರ Zoho ಸ್ನ್ಯಾಪ್‌ಶಾಟ್‌ಗಳು, ನೀವು ಸಿಂಕ್ ಮಾಡಿದಾಗ ರಿಫ್ರೆಶ್ ಆಗುತ್ತವೆ",
  "All records are up to date in Zoho.": "Zoho ದಲ್ಲಿ ಎಲ್ಲಾ ದಾಖಲೆಗಳು ನವೀಕೃತವಾಗಿವೆ.",
  "All Sales Orders": "ಎಲ್ಲಾ ಸೇಲ್ಸ್ ಆರ್ಡರ್‌ಗಳು",
  "All statuses": "ಎಲ್ಲಾ ಸ್ಥಿತಿಗಳು",
  "Amount, e.g. 0": "ಮೊತ್ತ, ಉದಾ. 0",
  "Approved app catalogue changes, customer and vendor contacts, and orders are queued for Zoho Inventory & Zoho Commerce. Click": "ಅನುಮೋದಿತ ಆ್ಯಪ್ ಕ್ಯಾಟಲಾಗ್ ಬದಲಾವಣೆಗಳು, ಗ್ರಾಹಕ ಮತ್ತು ಮಾರಾಟಗಾರರ ಸಂಪರ್ಕಗಳು ಹಾಗೂ ಆರ್ಡರ್‌ಗಳನ್ನು Zoho Inventory ಮತ್ತು Zoho Commerce ಗಾಗಿ ಸರದಿಯಲ್ಲಿ ಇರಿಸಲಾಗುತ್ತದೆ. ಕ್ಲಿಕ್ ಮಾಡಿ:",
  "Approved catalogue, contact, and order changes are queued for Zoho. Supported account data is read into separate snapshots when synchronized.": "ಅನುಮೋದಿತ ಕ್ಯಾಟಲಾಗ್, ಸಂಪರ್ಕ ಮತ್ತು ಆರ್ಡರ್ ಬದಲಾವಣೆಗಳನ್ನು Zoho ಗಾಗಿ ಸರದಿಯಲ್ಲಿ ಇರಿಸಲಾಗುತ್ತದೆ. ಸಿಂಕ್ ಮಾಡಿದಾಗ ಬೆಂಬಲಿತ ಖಾತೆ ಮಾಹಿತಿಯನ್ನು ಪ್ರತ್ಯೇಕ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್‌ಗಳಿಗೆ ಓದಲಾಗುತ್ತದೆ.",
  "Approved Catalogue:": "ಅನುಮೋದಿತ ಕ್ಯಾಟಲಾಗ್:",
  "Authorize securely using Zoho OAuth. Your Zoho password is never entered here.": "Zoho OAuth ಬಳಸಿ ಸುರಕ್ಷಿತವಾಗಿ ಅಧಿಕೃತಗೊಳಿಸಿ. ನಿಮ್ಮ Zoho ಪಾಸ್‌ವರ್ಡ್ ಅನ್ನು ಇಲ್ಲಿ ಎಂದಿಗೂ ನಮೂದಿಸುವುದಿಲ್ಲ.",
  "blocked order": "ತಡೆಹಿಡಿದ ಆರ್ಡರ್",
  "Check the connection and requested scopes": "ಸಂಪರ್ಕ ಮತ್ತು ಕೇಳಿದ ಅನುಮತಿ ವ್ಯಾಪ್ತಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ",
  "Check the connection and try again": "ಸಂಪರ್ಕ ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ",
  "Check the production sync migration and try again": "ಪ್ರೊಡಕ್ಷನ್ ಸಿಂಕ್ ಮೈಗ್ರೇಶನ್ ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ",
