  "Edits here are saved in Zoho Commerce. Payments, packages and invoices are still managed in Zoho.": "ಇಲ್ಲಿನ ತಿದ್ದುಪಡಿಗಳನ್ನು Zoho Commerce ನಲ್ಲಿ ಉಳಿಸಲಾಗುತ್ತದೆ. ಪಾವತಿಗಳು, ಪ್ಯಾಕೇಜ್‌ಗಳು ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್‌ಗಳನ್ನು ಈಗಲೂ Zoho ದಲ್ಲೇ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ.",
