  "Synced {0} products and {1} coupons from Zoho Commerce": "Zoho Commerce ಇಂದ {0} ಉತ್ಪನ್ನಗಳು ಮತ್ತು {1} ಕೂಪನ್‌ಗಳನ್ನು ಸಿಂಕ್ ಮಾಡಲಾಗಿದೆ",
  "Synced the available Zoho read-only data": "ಲಭ್ಯವಿರುವ Zoho ಓದಲು-ಮಾತ್ರ ಮಾಹಿತಿಯನ್ನು ಸಿಂಕ್ ಮಾಡಲಾಗಿದೆ",
  "Synced Zoho data": "ಸಿಂಕ್ ಮಾಡಿದ Zoho ಮಾಹಿತಿ",
  "Syncing account data…": "ಖಾತೆ ಮಾಹಿತಿ ಸಿಂಕ್ ಆಗುತ್ತಿದೆ…",
  "Syncing catalog…": "ಕ್ಯಾಟಲಾಗ್ ಸಿಂಕ್ ಆಗುತ್ತಿದೆ…",
  "Tax records": "ತೆರಿಗೆ ದಾಖಲೆಗಳು",
  "The integration now automatically validates Indian GSTIN formats, treats unverified or retail consumer numbers safely, and preserves customer inputs in order notes so Zoho write will succeed. Click Retry all failed to push them.": "ಸಂಯೋಜನೆಯು ಈಗ ಭಾರತೀಯ GSTIN ಸ್ವರೂಪಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪರಿಶೀಲಿಸುತ್ತದೆ, ಪರಿಶೀಲಿಸದ ಅಥವಾ ಚಿಲ್ಲರೆ ಗ್ರಾಹಕ ಸಂಖ್ಯೆಗಳನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ನಿರ್ವಹಿಸುತ್ತದೆ ಮತ್ತು ಗ್ರಾಹಕರ ನಮೂದುಗಳನ್ನು ಆರ್ಡರ್ ಟಿಪ್ಪಣಿಗಳಲ್ಲಿ ಉಳಿಸುತ್ತದೆ, ಇದರಿಂದ Zoho ಬರಹ ಯಶಸ್ವಿಯಾಗುತ್ತದೆ. ಅವನ್ನು ಕಳುಹಿಸಲು ವಿಫಲವಾದ ಎಲ್ಲವನ್ನೂ ಮರುಪ್ರಯತ್ನಿಸಿ ಕ್ಲಿಕ್ ಮಾಡಿ.",
  "These are Zoho records. They do not create ShamiBusiness orders.": "ಇವು Zoho ದಾಖಲೆಗಳು. ಇವು ShamiBusiness ಆರ್ಡರ್‌ಗಳನ್ನು ರಚಿಸುವುದಿಲ್ಲ.",
  "This page shows a snapshot imported from Zoho. Sales orders can be edited here with": "ಈ ಪುಟ Zoho ಇಂದ ಆಮದು ಮಾಡಿದ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್ ಅನ್ನು ತೋರಿಸುತ್ತದೆ. ಸೇಲ್ಸ್ ಆರ್ಡರ್‌ಗಳನ್ನು ಇಲ್ಲಿ ಇದರ ಮೂಲಕ ಸಂಪಾದಿಸಬಹುದು:",
  "to import the latest Zoho values for everything else.": "ಉಳಿದ ಎಲ್ಲದಕ್ಕೂ ಇತ್ತೀಚಿನ Zoho ಮೌಲ್ಯಗಳನ್ನು ಆಮದು ಮಾಡಲು.",
  "To read new changes from Zoho, choose Sync account data.": "Zoho ಇಂದ ಹೊಸ ಬದಲಾವಣೆಗಳನ್ನು ಓದಲು, ಖಾತೆ ಮಾಹಿತಿ ಸಿಂಕ್ ಮಾಡಿ ಆಯ್ಕೆಮಾಡಿ.",
  "to send queued changes immediately. Otherwise, the scheduled sync sends queued changes every 15 minutes. To import changes made inside Zoho, click": "ಸರದಿಯಲ್ಲಿರುವ ಬದಲಾವಣೆಗಳನ್ನು ತಕ್ಷಣ ಕಳುಹಿಸಲು. ಇಲ್ಲದಿದ್ದರೆ, ನಿಗದಿತ ಸಿಂಕ್ ಪ್ರತಿ 15 ನಿಮಿಷಗಳಿಗೆ ಸರದಿಯ ಬದಲಾವಣೆಗಳನ್ನು ಕಳುಹಿಸುತ್ತದೆ. Zoho ದಲ್ಲಿ ಮಾಡಿದ ಬದಲಾವಣೆಗಳನ್ನು ಆಮದು ಮಾಡಲು, ಕ್ಲಿಕ್ ಮಾಡಿ:",
  "Updated {0}": "ನವೀಕರಿಸಲಾಗಿದೆ {0}",
