  "If this Auth account exists, Supabase will send a password setup link. Open the latest email on this device to continue.": "ಈ Auth ಖಾತೆ ಇದ್ದರೆ, Supabase ಪಾಸ್‌ವರ್ಡ್ ಹೊಂದಿಸುವ ಲಿಂಕ್ ಕಳುಹಿಸುತ್ತದೆ. ಮುಂದುವರಿಯಲು ಇದೇ ಸಾಧನದಲ್ಲಿ ಇತ್ತೀಚಿನ ಇಮೇಲ್ ತೆರೆಯಿರಿ.",
