  "Shop raw, steam and basmati rice, S1 sugar 50 kg bags and sunflower and groundnut oil tins at godown prices. GST invoice, pickup or delivery from Challakere and Hubli.": "ಕಚ್ಚಾ, ಸ್ಟೀಮ್ ಮತ್ತು ಬಾಸ್ಮತಿ ಅಕ್ಕಿ, S1 ಸಕ್ಕರೆಯ 50 kg ಚೀಲಗಳು ಹಾಗೂ ಸೂರ್ಯಕಾಂತಿ ಮತ್ತು ಕಡಲೆಕಾಯಿ ಎಣ್ಣೆಯ ಟಿನ್‌ಗಳನ್ನು ಗೋದಾಮು ಬೆಲೆಯಲ್ಲಿ ಖರೀದಿಸಿ. GST ಇನ್‌ವಾಯ್ಸ್, ಚಳ್ಳಕೆರೆ ಮತ್ತು ಹುಬ್ಬಳ್ಳಿಯಿಂದ ಪಿಕಪ್ ಅಥವಾ ಡೆಲಿವರಿ.",
