  "Why should this review be moderated?": "ಈ ವಿಮರ್ಶೆಯನ್ನು ಏಕೆ ಪರಿಶೀಲಿಸಬೇಕು?",
  "Write your response...": "ನಿಮ್ಮ ಉತ್ತರ ಬರೆಯಿರಿ...",
  "Auto-accept new orders": "ಹೊಸ ಆರ್ಡರ್‌ಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸ್ವೀಕರಿಸಿ",
  "Bank details must be verified through vendor onboarding. They are not editable from this screen.": "ಬ್ಯಾಂಕ್ ವಿವರಗಳನ್ನು ಮಾರಾಟಗಾರರ ಸೇರ್ಪಡೆ ಪ್ರಕ್ರಿಯೆಯ ಮೂಲಕ ಪರಿಶೀಲಿಸಬೇಕು. ಅವುಗಳನ್ನು ಈ ಪರದೆಯಿಂದ ಸಂಪಾದಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "Cash on delivery is disabled": "ಕ್ಯಾಶ್ ಆನ್ ಡೆಲಿವರಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ",
  "Cash on delivery is not accepted on Grain Bazar. Customers pay by UPI or bank transfer: the advance set by the admin (30% by default) is needed before you accept an order, and the full balance before it is dispatched or handed over at pickup.": "Grain Bazar ನಲ್ಲಿ ಕ್ಯಾಶ್ ಆನ್ ಡೆಲಿವರಿ ಸ್ವೀಕರಿಸಲಾಗುವುದಿಲ್ಲ. ಗ್ರಾಹಕರು UPI ಅಥವಾ ಬ್ಯಾಂಕ್ ವರ್ಗಾವಣೆಯ ಮೂಲಕ ಪಾವತಿಸುತ್ತಾರೆ: ನೀವು ಆರ್ಡರ್ ಸ್ವೀಕರಿಸುವ ಮೊದಲು ನಿರ್ವಾಹಕರು ನಿಗದಿಪಡಿಸಿದ ಮುಂಗಡ (ಡೀಫಾಲ್ಟ್ ಆಗಿ 30%) ಅಗತ್ಯ, ಮತ್ತು ರವಾನಿಸುವ ಅಥವಾ ಪಿಕಪ್‌ನಲ್ಲಿ ಹಸ್ತಾಂತರಿಸುವ ಮೊದಲು ಪೂರ್ಣ ಬಾಕಿ ಅಗತ್ಯ.",
  "Configure store and account preferences": "ಅಂಗಡಿ ಮತ್ತು ಖಾತೆಯ ಆದ್ಯತೆಗಳನ್ನು ಹೊಂದಿಸಿ",
  Fulfilment: "ಆರ್ಡರ್ ಪೂರೈಕೆ",
  "Password changes update your authenticated account and require at least 8 characters. Two-factor enrollment is not available in this panel.": "ಪಾಸ್‌ವರ್ಡ್ ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ದೃಢೀಕೃತ ಖಾತೆಯನ್ನು ನವೀಕರಿಸುತ್ತವೆ ಮತ್ತು ಕನಿಷ್ಠ 8 ಅಕ್ಷರಗಳು ಬೇಕು. ಎರಡು-ಹಂತದ ದೃಢೀಕರಣ ನೋಂದಣಿ ಈ ವಿಭಾಗದಲ್ಲಿ ಲಭ್ಯವಿಲ್ಲ.",
  "Password updated": "ಪಾಸ್‌ವರ್ಡ್ ನವೀಕರಿಸಲಾಗಿದೆ",
  "Payment Settings": "ಪಾವತಿ ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
  "Preference saved for your account. Order processing still follows platform rules.": "ನಿಮ್ಮ ಖಾತೆಗೆ ಆದ್ಯತೆಯನ್ನು ಉಳಿಸಲಾಗಿದೆ. ಆರ್ಡರ್ ಪ್ರಕ್ರಿಯೆ ಈಗಲೂ ವೇದಿಕೆಯ ನಿಯಮಗಳನ್ನೇ ಅನುಸರಿಸುತ್ತದೆ.",
