  "This app has no vendor MFA enrollment or challenge flow yet. The saved preference control was removed because it did not change sign-in security.": "ಈ ಆ್ಯಪ್‌ನಲ್ಲಿ ಮಾರಾಟಗಾರರಿಗೆ ಬಹು-ಹಂತದ ದೃಢೀಕರಣ (MFA) ನೋಂದಣಿ ಅಥವಾ ಪರಿಶೀಲನಾ ಪ್ರಕ್ರಿಯೆ ಇನ್ನೂ ಇಲ್ಲ. ಉಳಿಸಿದ ಆದ್ಯತೆ ನಿಯಂತ್ರಣವು ಲಾಗಿನ್ ಭದ್ರತೆಯನ್ನು ಬದಲಾಯಿಸದ ಕಾರಣ ಅದನ್ನು ತೆಗೆದುಹಾಕಲಾಗಿದೆ.",
