  "Stock management console for Grain Bazar marketplace vendors.": "Grain Bazar ಮಾರುಕಟ್ಟೆ ಮಾರಾಟಗಾರರಿಗಾಗಿ ದಾಸ್ತಾನು ನಿರ್ವಹಣಾ ಕನ್ಸೋಲ್.",
  "Sign in to the vendor panel with your provisioned business account.": "ನಿಮಗೆ ನೀಡಲಾದ ವ್ಯವಹಾರ ಖಾತೆಯೊಂದಿಗೆ ಮಾರಾಟಗಾರರ ವಿಭಾಗಕ್ಕೆ ಲಾಗಿನ್ ಮಾಡಿ.",
  "Manage your Grain Bazar listings, orders, stock and earnings.": "ನಿಮ್ಮ Grain Bazar ಉತ್ಪನ್ನ ಪಟ್ಟಿಗಳು, ಆರ್ಡರ್‌ಗಳು, ದಾಸ್ತಾನು ಮತ್ತು ಆದಾಯವನ್ನು ನಿರ್ವಹಿಸಿ.",
  "Vendor order detail, items and status timeline.": "ಮಾರಾಟಗಾರರ ಆರ್ಡರ್ ವಿವರ, ಐಟಂಗಳು ಮತ್ತು ಸ್ಥಿತಿಯ ಕಾಲಾನುಕ್ರಮ.",
