  "Order management for Grain Bazar marketplace vendors.": "Grain Bazar ಮಾರುಕಟ್ಟೆ ಮಾರಾಟಗಾರರಿಗಾಗಿ ಆರ್ಡರ್ ನಿರ್ವಹಣೆ.",
  "List a new product on the Grain Bazar marketplace.": "Grain Bazar ಮಾರುಕಟ್ಟೆಯಲ್ಲಿ ಹೊಸ ಉತ್ಪನ್ನವನ್ನು ಪಟ್ಟಿ ಮಾಡಿ.",
