  "Checkouts whose customer has not paid yet. Their stock is held; they become orders the moment the bank alert (or your confirmation) matches the payment, and end on their own when the time is up.": "ಗ್ರಾಹಕರು ಇನ್ನೂ ಪಾವತಿಸದ ಚೆಕ್‌ಔಟ್‌ಗಳು. ಇವುಗಳ ದಾಸ್ತಾನು ಕಾಯ್ದಿರಿಸಲಾಗಿದೆ; ಬ್ಯಾಂಕ್ ಸೂಚನೆ (ಅಥವಾ ನಿಮ್ಮ ದೃಢೀಕರಣ) ಪಾವತಿಗೆ ಹೊಂದಿದ ತಕ್ಷಣ ಇವು ಆರ್ಡರ್‌ಗಳಾಗುತ್ತವೆ, ಸಮಯ ಮುಗಿದಾಗ ತಾವಾಗಿಯೇ ಕೊನೆಗೊಳ್ಳುತ್ತವೆ.",
  "Continue to pay": "ಪಾವತಿಗೆ ಮುಂದುವರಿಸಿ",
  "Could not cancel": "ರದ್ದುಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
