  "Demo only: the bank SMS for this payment arrives": "ಡೆಮೊ ಮಾತ್ರ: ಈ ಪಾವತಿಯ ಬ್ಯಾಂಕ್ SMS ಬರುತ್ತದೆ",
  "Demo: receive this SMS": "ಡೆಮೊ: ಈ SMS ಸ್ವೀಕರಿಸಿ",
