  "Enter your name": "ನಿಮ್ಮ ಹೆಸರು ನಮೂದಿಸಿ",
  "Grain Bazar sells and delivers only around our godowns, so orders can't be placed for this PIN code for now.": "Grain Bazar ನಮ್ಮ ಗೋದಾಮುಗಳ ಸುತ್ತಮುತ್ತ ಮಾತ್ರ ಮಾರಾಟ ಮತ್ತು ಡೆಲಿವರಿ ಮಾಡುತ್ತದೆ, ಆದ್ದರಿಂದ ಈ PIN ಕೋಡ್‌ಗೆ ಸದ್ಯಕ್ಕೆ ಆರ್ಡರ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "Just browsing, hide this": "ಸುಮ್ಮನೆ ನೋಡುತ್ತಿದ್ದೇನೆ, ಇದನ್ನು ಮರೆಮಾಡಿ",
  "Map: PIN {0} is outside our delivery area": "ನಕ್ಷೆ: PIN {0} ನಮ್ಮ ಡೆಲಿವರಿ ಪ್ರದೇಶದ ಹೊರಗಿದೆ",
  "Not served yet": "ಇನ್ನೂ ಸೇವೆ ಇಲ್ಲ",
