  "The scheduled sync checks supported linked-order shipment milestones every 15 minutes and applies eligible fulfillment changes to Grain Bazar orders. Imported Zoho sales order snapshots still need a manual \"Sync account data\" refresh.": "ನಿಗದಿತ ಸಿಂಕ್ ಪ್ರತಿ 15 ನಿಮಿಷಕ್ಕೊಮ್ಮೆ ಜೋಡಿಸಿದ ಆರ್ಡರ್‌ಗಳ ಸಾಗಣೆ ಹಂತಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಅರ್ಹ ಬದಲಾವಣೆಗಳನ್ನು Grain Bazar ಆರ್ಡರ್‌ಗಳಿಗೆ ಅನ್ವಯಿಸುತ್ತದೆ. ಆಮದು ಮಾಡಿದ Zoho ಸೇಲ್ಸ್ ಆರ್ಡರ್ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್‌ಗಳಿಗೆ ಇನ್ನೂ ಕೈಯಾರೆ \"Sync account data\" ರಿಫ್ರೆಶ್ ಬೇಕು.",
